mapper.select:
SELECT id, name, avatar, owner_id, notice, max_members, created_at, dissolved_at
FROM im_group
WHERE id = #{id}

mapper.update:
UPDATE im_group
SET dissolved_at = NOW()
WHERE id = #{id}

UPDATE im_group
SET owner_id = #{ownerId}
WHERE id = #{id}

UPDATE im_group
SET avatar = #{avatar},
    notice = #{notice}
WHERE id = #{id}
  AND dissolved_at IS NULL
